package dev.continuousimprovement.dispatcher;
import dev.continuousimprovement.dispatcher.agent.*;import dev.continuousimprovement.dispatcher.gateway.*;import java.net.URI;import java.nio.file.*;import java.util.*;
public final class DispatcherMain {
 public static void main(String[] args)throws Exception{Map<String,String> env=System.getenv();String token=required(env,"DISPATCHER_TOKEN");Path repo=Path.of(required(env,"DISPATCHER_REPOSITORY")).toAbsolutePath();Path defaultScratch=Path.of(System.getProperty("user.home"),"Documents","continuous-improvement");String configuredScratch=env.get("DISPATCHER_SCRATCH");Path scratch=(configuredScratch==null||configuredScratch.isBlank()?defaultScratch:Path.of(configuredScratch)).toAbsolutePath();var runner=new ProcessRunner();var control=new GhSupabaseControlPlane(runner,repo,URI.create(required(env,"DISPATCHER_ENDPOINT")),token);var dispatcher=new Dispatcher(control,List.of(new CodexAdapter(runner,env.getOrDefault("CODEX_BIN","codex")),new ClaudeAdapter(runner,env.getOrDefault("CLAUDE_BIN","claude"))),runner,new VerificationGate(runner,env.containsKey("MAX_DIFF_LINES")?Integer.parseInt(env.get("MAX_DIFF_LINES")):2000),repo,scratch);System.out.println("{\"outcome\":\""+dispatcher.runOnce()+"\"}");}
 private static String required(Map<String,String> env,String name){String v=env.get(name);if(v==null||v.isBlank())throw new IllegalArgumentException(name+" is required");return v;}
}
